<?php declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';use App\Services\Auth;use App\Services\SubscriptionEligibilityService;use App\Security\Csrf;use App\Support\Url;Auth::requirePermission('SUBSCRIPTION_REQUEST_OWN');$id=(int)($_GET['id']??0);$subs=SubscriptionEligibilityService::ownSubscriptions();$request=$subs['pending'];if(!$request||(int)$request['subscription_id']!==$id){http_response_code(404);exit('Pending subscription request not found.');}$errors=[];$prices=['GOLD'=>35000,'PREMIUM'=>55000,'PLATINUM'=>100500];if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))$errors[]='Invalid form token.';else try{SubscriptionEligibilityService::submitPaymentDetails($id,$_POST,(int)Auth::user()['id']);header('Location: '.Url::to('carrier/subscription.php?payment=1'));exit;}catch(RuntimeException$e){$errors[]=$e->getMessage();}}$pageTitle='Subscription Payment Details';require BASE_PATH.'/app/Views/layout/header.php';?>
<div class="page-head"><div><span class="eyebrow dark">Manual bank payment</span><h1>Enter bank transfer details</h1><p><?=h($request['plan_name'])?> plan · <strong>TSh <?=h(number_format((float)($prices[$request['plan_code']]??0),0))?></strong></p></div><span class="status-pill status-requested">Awaiting verification</span></div><?php foreach($errors as$e):?><div class="error"><?=h($e)?></div><?php endforeach;?><div class="notice">Bank and mobile-money integrations are not yet connected. Complete your transfer using the official payment instructions provided by McCollins, then record the transfer below. Operations will verify it before activation or future scheduling. For security, this portal does not collect card numbers, expiry dates or CVC values.</div><form method="post" class="card feature-card"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><div class="form-grid"><div class="field"><label>Bank used for transfer</label><input name="bank_name" maxlength="120" required placeholder="Bank name"></div><div class="field"><label>Payer / account holder name</label><input name="payer_name" maxlength="160" required></div><div class="field"><label>Bank transaction reference</label><input name="payment_reference" maxlength="96" required pattern="[A-Za-z0-9._:/-]+" placeholder="Example: TXN-123456"></div><div class="field"><label>Transfer date</label><input name="transfer_date" type="date" required value="<?=h(date('Y-m-d'))?>"></div></div><div class="actions"><button class="button">Submit payment details</button><a class="button secondary" href="<?=h(Url::to('carrier/subscription.php'))?>">Change selected plan</a></div></form><?php require BASE_PATH.'/app/Views/layout/footer.php';
